import java.util.Scanner;

public class Main {
    static final int MAXN = 30;
    static final long MOD = 1000000007;
    static long n;
    static int m;
    static int[][][] f = new int[65][35][35];
    static int[] s = new int[65];
    static int num = 0;
    static int[][] g = new int[35][35];
    static int[] A = new int[35];
    static int[] B = new int[35];

    static int Dec(int x, int y) {
        if (x < m) {
            return (x - y + m) % m;
        } else {
            return (x - y + m) % m;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextInt();

        long t = n;
        while (t > 0) {
            s[++num] = (int)(t % m);
            t /= m;
        }

        for (int i = 1; i <= m; ++i) {
            f[1][i][i] = 1;
        }
        for (int i = 0; i <= m; ++i) {
            f[1][0][i] = 1;
        }

        for (int i = 2; i <= num; ++i) {
            for (int j = 0; j <= m; ++j) {
                f[i][j][j] = 1;
            }
            for (int j = 0; j < m; ++j) {
                for (int a = 0; a <= m; ++a) {
                    for (int b = 0; b <= m; ++b) {
                        for (int c = 0; c <= m; ++c) {
                            g[a][c] = (int)((g[a][c] + (long)f[i - 1][Dec(a, j)][Dec(b, j)] * f[i][b][c]) % MOD);
                        }
                    }
                }
                for (int a = 0; a <= m; ++a) {
                    for (int b = 0; b <= m; ++b) {
                        f[i][a][b] = g[a][b];
                        g[a][b] = 0;
                    }
                }
            }
        }

        for (int i = 0; i <= m; ++i) {
            A[i] = 1;
        }

        for (int i = 1; i <= num; ++i) {
            int S = 0;
            for (int j = i + 1; j <= num; ++j) {
                S = (S + s[j]) % m;
            }
            for (; s[i] > 0; --s[i]) {
                int dec = (S + s[i]) % m;
                for (int a = 0; a <= m; ++a) {
                    for (int b = 0; b <= m; ++b) {
                        B[b] = (int)((B[b] + (long)A[a] * f[i][Dec(a, dec)][Dec(b, dec)]) % MOD);
                    }
                }
                for (int a = 0; a <= m; ++a) {
                    A[a] = B[a];
                    B[a] = 0;
                }
            }
        }

        System.out.println(A[m]);
        sc.close();
    }
}

